<script setup>
import {ref,onMounted,computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {get} from '../api/client';import FoodRecordForm from '../components/FoodRecordForm.vue';import StatusBadge from '../components/StatusBadge.vue';import EvidenceViewer from '../components/EvidenceViewer.vue';import CursorPager from '../components/CursorPager.vue';import {Search,ArrowUpRight,Package,History,CalendarDays} from 'lucide-vue-next';const route=useRoute(),router=useRouter();const isPrice=computed(()=>route.path==='/prices');const priceFilters=ref({spec:'',supplier:'',amount_min:'',amount_max:'',unit:''});const data=ref({items:[]}),product=ref(null),history=ref([]),substitutions=ref([]),error=ref(''),query=ref(''),scheduled=ref(false),asOf=ref(new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Seoul'})),selected=ref([]);async function load(cursor=''){try{if(route.params.id){product.value=await get('/products/'+route.params.id+'?as_of='+asOf.value);history.value=(await get('/products/'+route.params.id+'/history?limit=100')).items;const pp=await get('/prices?product_id='+route.params.id+'&include_scheduled=true&as_of='+asOf.value);data.value=pp;substitutions.value=(await Promise.all(product.value.supplier_items.map(i=>get('/supplier-items/'+i.id+'/substitutions?include_scheduled=true')))).flatMap(r=>r.items)}else data.value=await get((isPrice.value?'/prices?as_of='+asOf.value+'&include_scheduled='+scheduled.value+'&'+new URLSearchParams(Object.entries(priceFilters.value).filter(([,v])=>v!=='')):'/products?')+'&q='+encodeURIComponent(query.value)+(cursor?'&cursor='+cursor:''))}catch(e){error.value=e.message}}onMounted(()=>load());const money=n=>Number(n).toLocaleString('ko-KR');const kinds={create_product:'제품 등록',create_variant:'규격 등록',create_supplier_item:'공급 품목 등록',food_archived:'식품 목록에서 삭제',food_restored:'식품 복구',edit_food_profile:'식품 정보 직접 수정',set_food_profile:'표준 식품 정보 변경',set_price:'단가 변경',set_availability:'공급 상태 변경',set_product_status:'제품 상태 변경',set_substitution:'대체품 연결'};
</script><template><div class="page-heading"><div><div class="eyebrow">{{product?'PRODUCT RECORD':isPrice?'PRICE DIRECTORY':'PRODUCT DIRECTORY'}}</div><h1>{{product?product.name:isPrice?'단가표 조회':'식품 목록'}}</h1><p class="muted">{{product?'제품의 현재 정보와 변경 과정을 함께 확인하세요.':'확인된 식품 정보를 기준일에 맞게 찾아보세요.'}}</p></div><RouterLink v-if="product" to="/products" class="secondary">식품 목록</RouterLink><RouterLink v-else to="/products" class="secondary">식품 DB</RouterLink><span v-if="!product" class="source-chip"><span class="pulse"></span> 승인·반영된 데이터</span></div><p class="error" v-if="error">{{error}}</p><template v-if="product"><div class="product-overview panel"><div class="product-visual"><Package :size="42" stroke-width="1.1"/></div><div><div class="row"><StatusBadge :value="product.status"/><span class="small muted">제품 v{{product.version}}</span></div><h2>{{product.name}}</h2><p class="muted">{{product.variants.length}}개 규격</p></div></div><div class="two-col"><section class="panel"><div class="panel-heading"><h2>규격 및 공급 정보</h2></div><article v-for="v in product.variants" class="variant-block"><h3>{{v.spec_original}} <span v-if="v.archived" class="badge">삭제한 식품</span></h3><FoodRecordForm v-if="v.food_record" :model-value="v.food_record" readonly/><div v-for="i in product.supplier_items.filter(x=>x.variant_id===v.id)" class="row between"><span class="small">{{i.supplier_code||'품목코드 없음'}} · 판매 {{i.sales_unit}}</span><StatusBadge :value="i.availability?.status||'unknown'"/></div></article><div v-for="s in substitutions" class="variant-block"><h3>대체품 안내</h3><p>{{s.description_original}}</p><div v-for="g in s.groups"><small>{{g.selection==='all'?'함께 구성':'택 1'}}</small><button v-for="m in g.members" class="link" @click="async()=>{const list=await get('/supplier-items');const item=list.items.find(x=>x.id===m.supplier_item_ref.id);if(item){const products=await get('/products');for(const p of products.items){const detail=await get('/products/'+p.id);if(detail.supplier_items.some(x=>x.id===item.id)){router.push('/products/'+p.id);break}}}}">대체 상품 보기 ↗</button></div></div></section><section class="panel"><div class="panel-heading"><h2>단가 정보</h2></div><div v-for="p in data.items" class="price-record" @click="selected=p.evidence_ids"><div class="row between"><span>{{p.spec_label}}</span><StatusBadge :value="p.effective_state"/></div><strong>{{money(p.value.amount)}}<small>원 / {{p.value.quantity}}{{p.value.unit}}</small></strong><small class="muted">{{p.period.effective_from}}부터 · 세금 {{p.value.tax==='unknown'?'미확인':p.value.tax}}</small><span class="link small">근거 확인 ↗</span></div></section></div><section class="panel timeline-panel"><div class="panel-heading"><div><div class="eyebrow">CHANGE HISTORY</div><h2>식품별 변경 이력</h2></div><span class="small muted">이전 기록은 삭제되지 않습니다.</span></div><article v-for="h in history" class="timeline-item"><div class="timeline-dot"></div><small class="muted">{{new Date(h.recorded_at).toLocaleString('ko-KR')}}</small><h3>{{kinds[h.kind]||h.kind}}</h3><p class="small muted">{{h.reason||h.after?.reason?.summary||'근거와 함께 등록된 정보'}}</p><div class="row"><RouterLink :to="'/history/'+h.id" class="small">변경 전·후 보기 ↗</RouterLink><button class="link small" @click="selected=h.evidence_ids">원문 근거 보기</button><RouterLink v-if="h.proposal_id" :to="'/reviews/'+h.proposal_id" class="small">검토 기록</RouterLink></div></article></section></template><section v-else class="panel"><div class="toolbar wrap"><form class="row" @submit.prevent="load()"><Search :size="17" class="muted"/><input v-model="query" placeholder="식품명·규격·공급처 검색" aria-label="식품 검색"><button class="secondary">검색</button></form><div v-if="isPrice" class="row wrap"><label class="inline-label">기준일 <input type="date" v-model="asOf" @change="load()"></label><label class="inline-label"><input type="checkbox" v-model="scheduled" @change="load()">적용 예정 포함</label></div></div><form v-if="isPrice" class="price-filter-bar" @submit.prevent="load()"><label>규격<input v-model="priceFilters.spec" placeholder="예: 1kg"></label><label>공급처<input v-model="priceFilters.supplier" placeholder="업체명"></label><label>최소 단가<input v-model="priceFilters.amount_min" inputmode="decimal" placeholder="원"></label><label>최대 단가<input v-model="priceFilters.amount_max" inputmode="decimal" placeholder="원"></label><label>단위<select v-model="priceFilters.unit"><option value="">전체</option><option v-for="u in ['kg','g','l','ml','ea','bag','pack','box']">{{u}}</option></select></label><button class="secondary">필터 적용</button></form><div class="table-scroll"><table v-if="isPrice"><thead><tr><th>식품 / 규격</th><th>공급처</th><th>단가</th><th>적용 시작일</th><th>상태</th><th>근거</th></tr></thead><tbody><tr v-for="p in data.items" :key="p.id"><td><RouterLink :to="'/products/'+p.product_id"><b>{{p.product_name}}</b><small class="cell-sub">{{p.spec_label}} · {{p.supplier_code}}</small></RouterLink></td><td>{{p.supplier.name}}</td><td class="money">{{money(p.value.amount)}}<small>원 / {{p.value.quantity}}{{p.value.unit}}</small><small class="cell-sub">{{p.value.tax==='unknown'?'세금 미확인':p.value.tax}} · {{p.value.condition_key}}</small></td><td>{{p.period.effective_from}}</td><td><StatusBadge :value="p.effective_state"/></td><td><button class="link" @click="selected=p.evidence_ids">근거 ↗</button></td></tr></tbody></table><table v-else><thead><tr><th>식품명</th><th>업체</th><th>상태</th><th>등록일</th><th></th></tr></thead><tbody><tr class="clickable" v-for="p in data.items" :key="p.id" @click="router.push('/products/'+p.id)"><td><div class="cell-title"><div class="mini-product"><Package :size="19"/></div><b>{{p.name}}</b></div></td><td>{{p.company_name||'—'}}</td><td><StatusBadge :value="p.status"/></td><td class="muted">{{new Date(p.created_at).toLocaleDateString('ko-KR')}}</td><td><ArrowUpRight :size="16"/></td></tr></tbody></table></div><p v-if="!data.items.length" class="empty">조회 결과가 없습니다. 검색어나 기준일을 확인하세요.</p><CursorPager :next="data.next_cursor" @next="load"/></section><div v-if="selected.length" class="modal-backdrop" @click.self="selected=[]"><div class="modal"><button class="close" @click="selected=[]" aria-label="닫기">×</button><EvidenceViewer :ids="selected"/></div></div><div class="demo-banner"><span class="demo-label">REFERENCE FIRST</span> 금액·규격·세금 조건은 반드시 원문 근거와 함께 확인하세요.</div></template>
